def fizzbuzz(n):
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append('FizzBuzz')
        elif i % 3 == 0:
            result.append('Fizz')
        elif i % 5 == 0:
            result.append('Buzz')
        else:
            result.append(str(i))
    return result

def parsear_duracion(s):
    total = 0
    import re
    for part in re.findall(r'(\d+)([hm])', s):
        num, unit = part
        if unit == 'h':
            total += int(num) * 60
        elif unit == 'm':
            total += int(num)
    return total

def es_palindromo(s):
    s = ''.join(c for c in s.lower() if c.isalnum())
    return s == s[::-1]

def aplanar(lista):
    resultado = []
    for elemento in lista:
        if isinstance(elemento, list):
            resultado.extend(aplanar(elemento))
        else:
            resultado.append(elemento)
    return resultado

def buscar(lista, x):
    inicio = 0
    fin = len(lista) - 1
    while inicio <= fin:
        medio = (inicio + fin) // 2
        if lista[medio] == x:
            return medio
        elif lista[medio] < x:
            inicio = medio + 1
        else:
            fin = medio - 1
    return -1

