def desde_romano(s):
    valores = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    for i in range(len(s) - 1, -1, -1):
        if i == len(s) - 1:
            total += valores[s[i]]
        else:
            if valores[s[i]] > valores[s[i + 1]]:
                total += valores[s[i]] - valores[s[i + 1]]
                i -= 1
            else:
                total += valores[s[i]]
    return total

def mayor_racha(lista):
    if not lista:
        return None
    max_len = 1
    max_elem = lista[0]
    current_len = 1
    current_elem = lista[0]
    for i in range(1, len(lista)):
        if lista[i] == lista[i - 1]:
            current_len += 1
            current_elem = lista[i]
        else:
            if current_len > max_len:
                max_len = current_len
                max_elem = current_elem
            current_len = 1
            current_elem = lista[i]
    if current_len > max_len:
        max_len = current_len
        max_elem = current_elem
    return (max_elem, max_len)

