def formatear_bytes(n):
    unidades = ['B', 'KB', 'MB', 'GB']
    if n == 0:
        return '0 B'
    for i in range(1, len(unidades) + 1):
        divisor = 1024 ** i
        if n < divisor:
            if i == 1:
                return f'{n / 1024:.1f} KB'
            else:
                return f'{n / divisor:.1f} {unidades[i]}'
    return f'{n} B'

