def contar_islas(grid):
    def flood_fill(i, j):
        stack = [(i, j)]
        while stack:
            x, y = stack.pop()
            if x < 0 or y < 0 or x >= len(grid) or y >= len(grid[0]) or grid[x][y] == 0:
                continue
            grid[x][y] = 0
            stack.extend([(x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)]

    count = 0
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 1:
                flood_fill(i, j)
                count += 1
    return count

def distancia(a, b):
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            cost = 0 if a[i - 1] == b[j - 1] else 1
            dp[i][j] = min(
                dp[i - 1][j] + 1,
                dp[i][j - 1] + 1,
                dp[i - 1][j - 1] + cost
            )
    return dp[m][n]

def a_base(n, base):
    if n == 0:
        return '0'
    digits = '0123456789abcdef'
    result = ''
    while n > 0:
        result = digits[n % base] + result
        n //= base
    return result

