    for elemento in lista:
        if isinstance(elemento, list):
            resultado.extend(aplanar_hasta(elemento, profundidad - 1))
        else:
            resultado.append(elemento)
    return resultado

def sumar_romanos(a, b):
    def to_int(roman):
        values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
        total = 0
        for i in range(len(roman)):
            if i + 1 < len(roman) and values[roman[i + 1]] > values[roman[i]]:
                total -= values[roman[i]]
            else:
                total += values[roman[i]]
        return total

    def to_roman(num):
        values = [
            (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
            (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
            (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')
        ]
        result = ''
        for val, sym in values:
            while num >= val:
                result += sym
                num -= val
        return result

    return to_roman(to_int(a) + to_int(b))

def obtener(d, camino, defecto=None):
    if not camino:
        return defecto
    for clave in camino.split('.'):
        try:
            d = d[clave]
        except (KeyError, TypeError):
            return defecto
    return d

